/**
 * Default stream-event handlers for the GitHub channel.
 */
import { buildGitHubBinding, formatGitHubOutboundComment, } from "./binding.js";
import { applyGitHubProgress } from "./progress.js";
/**
 * Built-in delivery: eyes reaction on turn start, optional Checks API run /
 * sticky banner via {@link GitHubProgressConfig}, post assistant text on
 * `message.completed`, and a short error comment on turn/session failure.
 */
export function buildDefaultGitHubEvents(options = {}) {
    const deliverReplies = options.deliverReplies !== false;
    const requiredSuccessfulTools = new Set(options.progress?.requireSuccessfulTools
        ?.map((toolName) => toolName.trim())
        .filter((toolName) => toolName !== "") ?? []);
    const toolOutcomesBySession = new Map();
    return {
        async "turn.started"(event, channel) {
            if (requiredSuccessfulTools.size > 0) {
                toolOutcomesBySession.set(event.sessionId, new Map());
            }
            await applyGitHubProgress({
                phase: "pending",
                sessionId: event.sessionId,
                channel,
                options,
            });
            if (options.progress?.reactions === false) {
                return;
            }
            if (channel.state.owner === "" || channel.state.repo === "") {
                return;
            }
            try {
                const { thread } = buildGitHubBinding({
                    config: options,
                    state: channel.state,
                });
                await thread.react("eyes");
            }
            catch {
                // Soft-fail: missing token / no triggering comment is fine.
            }
        },
        async "action.result"(event) {
            if (event.data.parentCallId !== undefined ||
                !requiredSuccessfulTools.has(event.data.toolName)) {
                return;
            }
            const outcomes = toolOutcomesBySession.get(event.sessionId) ?? new Map();
            outcomes.set(event.data.toolName, !event.data.isError && event.data.stubbed !== true);
            toolOutcomesBySession.set(event.sessionId, outcomes);
        },
        async "turn.completed"(event, channel) {
            const outcomes = toolOutcomesBySession.get(event.sessionId);
            const pipelineSucceeded = requiredSuccessfulTools.size === 0 ||
                [...requiredSuccessfulTools].every((toolName) => outcomes?.get(toolName) === true);
            toolOutcomesBySession.delete(event.sessionId);
            await applyGitHubProgress({
                phase: pipelineSucceeded ? "success" : "failure",
                sessionId: event.sessionId,
                channel,
                options,
            });
        },
        async "message.completed"(event, channel) {
            if (!deliverReplies) {
                return;
            }
            if (event.data.parentCallId !== undefined ||
                event.data.finishReason === "tool_call" ||
                event.data.text === "") {
                return;
            }
            if (channel.state.owner === "" || channel.state.repo === "") {
                return;
            }
            try {
                const { thread } = buildGitHubBinding({
                    config: options,
                    state: channel.state,
                });
                await thread.post(formatGitHubOutboundComment(event.data.text));
            }
            catch {
                // Soft-fail delivery so a missing token does not crash the session.
            }
        },
        async "turn.failed"(event, channel) {
            toolOutcomesBySession.delete(event.sessionId);
            await applyGitHubProgress({
                phase: "failure",
                sessionId: event.sessionId,
                channel,
                options,
            });
            await postFailure(channel, options, event.data.message);
        },
        async "session.failed"(event, channel) {
            toolOutcomesBySession.delete(event.sessionId);
            await applyGitHubProgress({
                phase: "failure",
                sessionId: event.sessionId,
                channel,
                options,
            });
            await postFailure(channel, options, event.data.message);
        },
    };
}
async function postFailure(channel, options, _error) {
    if (options.deliverReplies === false) {
        return;
    }
    if (channel.state.owner === "" || channel.state.repo === "") {
        return;
    }
    try {
        const { thread } = buildGitHubBinding({
            config: options,
            state: channel.state,
        });
        await thread.post(formatGitHubOutboundComment([
            "I hit an error while handling your request.",
            "",
            "Please try again, or reach out if it keeps failing.",
        ].join("\n")));
    }
    catch {
        // Soft-fail.
    }
}
